@Override
    public UserAccountVO queryUserAccountByAccountNo(String accountNo, UserAccountTypeEnum accountType) {
        UserLoginAccountDOKey key = new UserLoginAccountDOKey();
        key.setAccountNo(accountNo);
        key.setAccountType(accountType.name());
        UserLoginAccountDO userLoginAccountDO = userLoginAccountMapper.selectByPrimaryKey(key);
        if (userLoginAccountDO == null) {
            return null;
        }
        UserAccountVO userAccountVO = new UserAccountVO();
        userAccountVO.setAccountNo(accountNo);
        userAccountVO.setAccountType(accountType);
        userAccountVO.setUserId(userLoginAccountDO.getUserId().toString());
        userAccountVO.setPassword(userLoginAccountDO.getPassword());
        userAccountVO.setAccountStatus(userLoginAccountDO.getAccountStatus());
        userAccountVO.setAppCode(userLoginAccountDO.getAppCode());
        userAccountVO.setExpireTime(userLoginAccountDO.getExpireTime());
        userAccountVO.setExtendInfo(StringUtils.isBlank(userLoginAccountDO.getExtendInfo()) ? null :
                JSON.parseObject(userLoginAccountDO.getExtendInfo(), UserAccountExtendInfoVO.class));
        return userAccountVO;
    }

protected void createUserAccount(UserAccountVO userAccountVO, PartyTypeEnum partyType) {
        UserAccountVO accountVO = userInfrastructure.queryUserAccountByAccountNo(userAccountVO.getAccountNo(), userAccountVO.getAccountType());
        if (accountVO != null) {
            userAccountVO.setUserId(accountVO.getUserId());
            return;
        }
        if (userAccountVO.getUserId() == null) {
            Long userId = userCoreService.createUserId(userAccountVO.getAccountType(), userAccountVO.getAccountNo(), partyType);
            userAccountVO.setUserId(userId.toString());
        }
        userInfrastructure.saveUserAccount(userAccountVO);
    }

private String getUserId(UserInfoVO userInfoVO, AuthInfoVO authInfoVO) {
        //新用户需要创建登陆账号
        UserAccountVO branchNoAccount = new UserAccountVO();
        branchNoAccount.setAccountType(UserAccountTypeEnum.ALIPAY_CIC_TOKEN);
        branchNoAccount.setAccountNo(userInfoVO.getCertNo());
        AppVO app = ThreadLocalContextManager.getApp();
        if (app != null) {
            branchNoAccount.setAppCode(app.getAppCode());
        }
        branchNoAccount.setAuthApp(authInfoVO.getAuthApp());
        //创建登陆账户信息
        this.createUserAccount(branchNoAccount, PartyTypeEnum.NATURE);
        return branchNoAccount.getUserId();
    }

@Override
    public UserVO login(AuthInfoVO authInfoVO) {
        // 获取支付宝商保码授权信息
        AlipayCicAuthInfo alipayCicAuthInfo = alipayCicService.cicAuthInfo(authInfoVO.getAuthCode());
        // 转换userInfoVO
        UserInfoVO userInfoVO = convertUserInfo(alipayCicAuthInfo);
        // 用户信息校验
        verifyUserInfo(userInfoVO);
        // 获取userid
        String userId = getUserId(userInfoVO, authInfoVO);
        // 创建user
        UserVO userVO = createUser(userId);
        // 创建userInfo
        createUserInfo(userId, userInfoVO);

        return userVO;
    }

protected UserVO createUser(String userId) {
        UserVO userVO = userInfrastructure.queryUser(userId);
        //不存在创建新的用户信息
        if (userVO == null) {
            userVO = new UserVO();
            userVO.setUserId(userId);
            userInfrastructure.saveUser(userVO);
        }
        return userVO;
    }

@Override
    public UserVO queryUser(String userId) {
        UserDO userDO = userMapper.selectByPrimaryKey(Long.valueOf(userId));
        if (userDO == null) {
            return null;
        }
        UserVO userVO = new UserVO();
        userVO.setUserId(userDO.getUserId().toString());
        userVO.setNickname(userDO.getNickName());
        userVO.setAvatar(userDO.getAvatar());
        return userVO;
    }

private String getUserId(AliPayAuthInfo aliPayAuthInfo, AuthInfoVO authInfoVO) {
        //新用户需要先创建账号
        UserAccountVO userAccountVO = new UserAccountVO();
        userAccountVO.setAccountType(UserAccountTypeEnum.ZFB_USERID);
        userAccountVO.setAccountNo(aliPayAuthInfo.getAliPayUserId());
        userAccountVO.setUserId(aliPayAuthInfo.getUserId());
        //UserAccountVO设置授权应用名称、应用编号
        AppVO app = ThreadLocalContextManager.getApp();
        if (app != null) {
            userAccountVO.setAppCode(app.getAppCode());
        }
        userAccountVO.setAuthApp(authInfoVO.getAuthApp());
        //创建userAccount
        createUserAccount(userAccountVO, PartyTypeEnum.LEGAL);
        return aliPayAuthInfo.getUserId();
    }

private String getUserId(UserInfoVO userInfoVO, AuthInfoVO authInfoVO) {
        //新用户需要先创建账号
        UserAccountVO accountVO = new UserAccountVO();
        accountVO.setAccountType(UserAccountTypeEnum.HL_CUSTOMERID);
        accountVO.setAccountNo(new UserInfoExtendHelianVO(userInfoVO).getCustomerId());
        createUserAccount(accountVO, PartyTypeEnum.NATURE);
        //UserAccountVO设置授权应用名称、应用编号
        AppVO app = ThreadLocalContextManager.getApp();
        if (app != null) {
            accountVO.setAppCode(app.getAppCode());
        }
        accountVO.setAuthApp(authInfoVO.getAuthApp());
        // 返回
        return accountVO.getUserId();
    }
